  function generatedPlayerIdentity(id,pos,country,age,base){
    const z=GENERATED_NAME_PARTS[country]||GENERATED_NAME_PARTS[(clubCountryOf&&clubCountryOf())||'法国']||GENERATED_NAME_PARTS['法国'];
    const e=GENERATED_EN_PARTS[country]||GENERATED_EN_PARTS['法国'];
    const a=Math.abs(Number(id)||0), fi=a%z[0].length, li=Math.floor(a/z[0].length)%z[1].length, mi=Math.floor(a/(z[0].length*z[1].length))%z[0].length;
    const cjk=country==='中国'||country==='日本'||country==='韩国';
    const name=z[0][fi]+(cjk?'':((mi%3===0&&mi!==fi)?'·'+z[0][mi]+'·':'·'))+z[1][li];
    const en=cjk?(country==='日本'?(e[1][li]+' '+e[0][fi]):(e[0][fi]+' '+e[1][li])):(e[0][fi]+((mi%3===0&&mi!==fi)?' '+e[0][mi]+' ':' ')+e[1][li]);
    return {name,nameEn:en,age,position:pos,nationality:country,base};
  }

  // 去掉姓名池里的重复项，避免不同下标生成同一个名字
  (function normalizeNamePools(){
    for(const key of Object.keys(GENERATED_NAME_PARTS)){
      const parts=GENERATED_NAME_PARTS[key];
      if(Array.isArray(parts)&&parts.length===2){
        parts[0]=[...new Set(parts[0])];
        parts[1]=[...new Set(parts[1])];
      }
    }
    for(const key of Object.keys(GENERATED_EN_PARTS)){
      const parts=GENERATED_EN_PARTS[key];
      if(Array.isArray(parts)&&parts.length===2){
        parts[0]=[...new Set(parts[0])];
        parts[1]=[...new Set(parts[1])];
      }
    }
  })();
  // 每国一个递增计数器：姓名组合按顺序取用，天然不重复
  const GENERATED_NAME_CURSOR={};
  // 性能：姓名候选串缓存。
  // 原循环每一步都要重拼中英文名 + 两次正则清理；而候选只由 (国家, 候选下标, extra) 决定，
  // 与调用者无关。缓存后每步只剩两次 Set.has，世界创建 / 每月姓名整理的取名循环快数倍，
  // 生成的字符串保持逐字节相同（缓存值就是原来每一步算出的值）。
  const NAME_CANDIDATE_CACHE=new Map();
  const NAME_INITIALS='ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  function nameCandidateFor(country,cjk,surs,givens,eGivens,eSurs,N,M,idx,extra){
    const key=country+'|'+idx+'|'+extra;
    const hit=NAME_CANDIDATE_CACHE.get(key);
    if(hit)return hit;
    const fi=idx%N,li=Math.floor(idx/N)%M;
    const given=givens[fi%N]||'球员';
    const sur=surs[li%M]||'';
    const eG=eGivens[fi%eGivens.length]||given;
    const eS=eSurs[li%eSurs.length]||'';
    const initial=extra>0?NAME_INITIALS[(li+extra*7)%26]:'';
    let zh='',en='';
    if(cjk){
      // 第二字来自另一个名池下标，天然扩展出三字名
      const second=extra>0?(givens[(fi+extra*3+1)%N]||''):'';
      zh=sur+given+second;
      en=(eS+' '+eG+(second?' '+(eGivens[(fi+extra*3+1)%eGivens.length]||''):'')).trim();
    }else{
      zh=given+'·'+(initial?initial+'·':'')+sur;
      en=(eG+' '+(initial?initial+' ':'')+eS).trim();
    }
    zh=String(zh).replace(/[·\s]+$/,'').trim();
    en=String(en).replace(/\s+/g,' ').trim();
    const out={zh,en};
    NAME_CANDIDATE_CACHE.set(key,out);
    return out;
  }
  // NPC 取名：固定「姓 + 名」两段，中文/日文/韩文 2–3 字，避免超长堆叠
  // NPC 取名：中文/日文/韩文用「姓+名」，西文用「名·姓」，冲突用中间首字母
  function generatedPlayerIdentityForClub(id,pos,country,age,base,usedNames,clubSeed,index){
    const z=GENERATED_NAME_PARTS[country]||GENERATED_NAME_PARTS[(clubCountryOf&&clubCountryOf())||'法国']||GENERATED_NAME_PARTS['法国'];
    const e=GENERATED_EN_PARTS[country]||GENERATED_EN_PARTS['法国'];
    const cjk=country==='中国'||country==='日本'||country==='韩国';
    // 中日韩：表结构是 [姓, 名]；其他：表结构是 [名, 姓]
    const surs=(cjk?(z[0]||['']):(z[1]||[''])).filter(Boolean);
    const givens=(cjk?(z[1]||['球员']):(z[0]||['球员'])).filter(Boolean);
    const eGivens=(e[0]||[]).filter(Boolean);
    const eSurs=(e[1]||[]).filter(Boolean);
    const N=Math.max(1,givens.length),M=Math.max(1,surs.length);
    const total=N*M;
    if(GENERATED_NAME_CURSOR[country]==null)GENERATED_NAME_CURSOR[country]=Math.abs(hash(String(country)+'-'+String(id)))%total;
    for(let step=0;step<total+120;step++){
      const idx=((GENERATED_NAME_CURSOR[country]||0)+step)%total;
      const extra=Math.floor(step/total);
      const cand=nameCandidateFor(country,cjk,surs,givens,eGivens,eSurs,N,M,idx,extra);
      const zh=cand.zh,en=cand.en;
      if(!usedNames||(!usedNames.has(zh)&&!usedNames.has(en))){
        GENERATED_NAME_CURSOR[country]=(GENERATED_NAME_CURSOR[country]+step+1)%total;
        if(usedNames){usedNames.add(zh);usedNames.add(en)}
        return {nameZh:zh,name:zh,nameEn:en};
      }
    }
    // 完全耗尽时：西文用「名·首字母·姓」，CJK 用「姓+名+首字母」
    const li2=Math.floor((GENERATED_NAME_CURSOR[country]||0)/Math.max(1,N))%Math.max(1,M);
    const gi2=(GENERATED_NAME_CURSOR[country]||0)%Math.max(1,N);
    const init2=NAME_INITIALS[Math.floor(Math.random()*26)];
    const g2=(givens[gi2]||'球员'),s2=(surs[li2]||'');
    const out=cjk?(s2+g2+init2.toLowerCase()):(g2+'·'+init2+'·'+s2);
    const outEn=cjk?((eSurs[li2]||'')+' '+(eGivens[gi2]||'')+' '+init2).trim():((eGivens[gi2]||'')+' '+init2+' '+(eSurs[li2]||'')).trim();
    if(usedNames){usedNames.add(out);usedNames.add(outEn)}
    return {nameZh:out,name:out,nameEn:outEn};
  }

  function realPlayerForPosition(pos,index){const pool=REAL_PLAYER_POOLS[pos]||REAL_PLAYER_POOLS.CM;return pool[index%pool.length];}
  function realPlayerAge(name,fallback){return REAL_PLAYER_META[name]?.age||fallback;}

  function playerNamePair(p){const en=p?.nameEn||p?.name||'球员';const zh=p?.nameZh||REAL_PLAYER_ZH[en]||en;return {zh,en};}
  function playerNameHTML(p){const n=playerNamePair(p);return `<span class="player-name-stack"><span class="player-name-zh">${esc(n.zh)}</span><span class="player-name-en">${esc(n.en)}</span></span>`;}
  function applyRealPlayerNames(){for(const p of Object.values(state.players||{})){if(!p.nameEn&&p.name&&REAL_PLAYER_ZH[p.name])p.nameEn=p.name;if(!p.nameEn&&p.name&&!/^PUSER$/.test(p.id))p.nameEn=p.name;if(p.nameEn){p.nameZh=REAL_PLAYER_ZH[p.nameEn]||p.nameZh||p.nameEn;p.name=p.nameZh;}}}
  function makeUniqueGeneratedName(p,serial){
    const z=GENERATED_NAME_PARTS[p.nationality]||GENERATED_NAME_PARTS[(clubCountryOf&&clubCountryOf(p))||'法国']||GENERATED_NAME_PARTS['法国'];
    const e=GENERATED_EN_PARTS[p.nationality]||GENERATED_EN_PARTS['法国'];
    const n=z[0].length, m=z[1].length, a=Math.abs(Number(serial)||0), fi=a%n, li=Math.floor(a/n)%m, mi=Math.floor(a/(n*m))%n;
    const mid=(mi%3===0&&mi!==fi);
    const zh=z[0][fi]+(mid?'·'+z[0][mi]:'')+z[1][li];
    const en=e[0][fi]+(mid?' '+e[0][mi]:'')+' '+e[1][li];
    return {zh,en};
  }
  // 重名处理：真实球员优先保留原姓名，只有生成球员（或同一真人的重复记录）才会被改名。
  // 旧实现按遍历顺序先到先得，导致「武磊」这类真实球员被随机生成的重名球员挤成了假名字。
  // 真实球员跨俱乐部重复：保留更合理的一处（俱乐部声望高者优先，其次能力高者）
  // 统一整理：真实身份去重 + 生成球员按顺序重命名
  // 名字精简：多余的中名去掉，只保留「名 + 姓」两段
  // 名字精简：去掉多余中名，只保留两段；西文保持「名·姓」
  function compactPlayerName(zh,country){
    let name=String(zh||'').trim();
    if(!name)return name;
    name=name.replace(/[0-9]+$/,'').replace(/\s{2,}/g,' ').trim();
    const cjk=country==='中国'||country==='日本'||country==='韩国';
    if(cjk)return name.replace(/[·\s]/g,'').slice(0,4);
    const parts=name.split(/[·\s]+/).filter(Boolean).map(x=>x.length>6?x.slice(0,6):x);
    if(parts.length>=3)return parts[0]+'·'+parts[1]+'·'+parts[parts.length-1];
    if(parts.length===2)return parts[0]+'·'+parts[1];
    return name.slice(0,10);
  }

  function finalizeWorldNames(){
    const removedReal=dedupeRealPlayerIdentities();
    const usedZh=new Set(),usedEn=new Set();
    const all=Object.values(state.players);
    for(const pl of all){
      if(!pl.isRealPlayer)continue;
      usedZh.add(String(pl.name||''));
      usedEn.add(String(pl.nameEn||'').toLowerCase());
    }
    const counters={};
    let renamed=0;
    for(const pl of all){
      if(pl.isRealPlayer)continue;
      const compacted=compactPlayerName(pl.name,pl.nationality||'法国');
      if(compacted&&compacted!==pl.name){pl.name=compacted;pl.nameZh=compacted}
      const zh=String(pl.name||''),en=String(pl.nameEn||'');
      if(zh&&en&&!usedZh.has(zh)&&!usedEn.has(en.toLowerCase())){usedZh.add(zh);usedEn.add(en.toLowerCase());continue}
      const country=pl.nationality||'法国';
      const z=GENERATED_NAME_PARTS[country]||GENERATED_NAME_PARTS[(clubCountryOf&&clubCountryOf())||'法国']||GENERATED_NAME_PARTS['法国'];
      const e=GENERATED_EN_PARTS[country]||GENERATED_EN_PARTS['法国'];
      const n=z[0].length,m=z[1].length,cjk=country==='中国'||country==='日本'||country==='韩国';
      const total=n*m*m;
      if(counters[country]==null)counters[country]=Math.abs(hash(String(pl.id)))%total;
      let done=false;
      for(let step=0;step<total&&!done;step++){
        const idx=(counters[country]+step)%total;
        const fi=idx%n,li=Math.floor(idx/n)%m,mi=Math.floor(idx/(n*m))%m;
        const nz=cjk?(idx<n*m?z[0][fi]+z[1][li]:z[0][fi]+(z[1][li]+''+z[1][mi]).slice(0,3)):(z[0][fi]+'·'+z[1][li]+(idx<n*m?'':'·'+z[1][mi]));
        const ef=(e[0]||[])[fi%e[0].length],el=(e[1]||[])[li%e[1].length],em=(e[1]||[])[mi%e[1].length];
        const ne=cjk?(country==='日本'?(el+' '+ef):(ef+' '+el+(idx<n*m?'':' '+em))):(el+' '+ef+(idx<n*m?'':' '+em));
        if(usedZh.has(nz)||usedEn.has(ne.toLowerCase()))continue;
        pl.name=nz;pl.nameZh=nz;pl.nameEn=ne;
        usedZh.add(nz);usedEn.add(ne.toLowerCase());
        counters[country]=(idx+1)%total;
        done=true;renamed++;
      }
      if(!done){
        const idx=Math.abs(hash(String(pl.id)))%total,fi=idx%n,li=Math.floor(idx/n)%m;
        const nz=z[0][fi]+z[1][li]+z[1][(li+3)%m].slice(0,1);
        const ne=((e[0]||[])[fi%e[0].length])+' '+((e[1]||[])[li%e[1].length]);
        pl.name=nz;pl.nameZh=nz;pl.nameEn=ne;
        usedZh.add(nz);usedEn.add(ne.toLowerCase());
        renamed++;
      }
    }
    // 兜底硬去重：仍重名的生成球员，追加一个自然的末字，直到唯一
    const EXTRA=['翔','航','誠','蓮','駿','優','颯','湊','樹','蒼','輝','凛','旭','遼','匠','圭','蒼','岳','仁','玲'];
    const seen=new Set(),seenEn=new Set();
    for(const pl of Object.values(state.players)){
      if(pl.isRealPlayer){seen.add(String(pl.name||''));seenEn.add(String(pl.nameEn||'').toLowerCase());continue}
      const base=String(pl.name||'')||'球員';
      let candidate=base,k=0;
      while(seen.has(candidate)&&k<EXTRA.length*2){candidate=base+EXTRA[k%EXTRA.length];k++}
      if(candidate!==base)pl.name=candidate;
      if(pl.name)tick:; // 占位，避免误改
      pl.name=candidate;pl.nameZh=candidate;
      // 英文名也保证唯一：冲突时补一个首字母
      let en=String(pl.nameEn||candidate);
      let ek=0;
      while(seenEn.has(en.toLowerCase())&&ek<26){en=String(pl.nameEn||candidate)+' '+String.fromCharCode(65+ek);ek++}
      pl.nameEn=en;
      seen.add(candidate);seenEn.add(en.toLowerCase());
    }
    // 最后再精简一遍：改名分支可能又生成了三段式名字
    for(const pl of Object.values(state.players)){
      if(pl.isRealPlayer)continue;
      const c=compactPlayerName(pl.name,pl.nationality||'法国');
      if(c&&c!==pl.name){pl.name=c;pl.nameZh=c}
    }
    // 兜底：补齐缺失/异常的年龄、国籍、位置
    for(const pl of Object.values(state.players)){
      if(!(pl.age>=15&&pl.age<=46)){
        if(pl.birthDate){const d=(new Date(state.date+'-01T00:00:00Z')-new Date(String(pl.birthDate).slice(0,7)+'-01T00:00:00Z'))/31557600000;if(isFinite(d))pl.age=Math.max(16,Math.min(40,Math.round(d)))}
        if(!(pl.age>=15&&pl.age<=46))pl.age=24;
      }
      if(!pl.nationality||pl.nationality==='未知'){
        const club=pl.clubId&&state.clubs[pl.clubId];
        pl.nationality=(club&&club.countryId)||pl.nationality||'未知';
      }
      if(!pl.position||!POS.includes(pl.position))pl.position='CM';
    }
    // 按最终国籍统一重造 NPC 名字（修复个别国家被套用法语名的问题）
    (function rebuildNames(){
      const usedBy={};
      const bucketFor=(c)=>{if(!usedBy[c])usedBy[c]=new Set();return usedBy[c]};
      for(const pl of Object.values(state.players))if(pl.isRealPlayer)bucketFor(pl.nationality||'法国').add(String(pl.name||''));
      for(const pl of Object.values(state.players)){
        if(pl.isRealPlayer)continue;
        const country=pl.nationality&&pl.nationality!=='未知'?pl.nationality:(pl.clubId&&state.clubs[pl.clubId]?state.clubs[pl.clubId].countryId:'法国');
        pl.nationality=country;
        const bucket=bucketFor(country);
        const idn=generatedPlayerIdentityForClub(pl.id,pl.position||'CM',country,pl.age||22,Math.round(pl.ca||60),bucket,0,0);
        pl.name=idn.name;pl.nameZh=idn.name;pl.nameEn=idn.nameEn;
      }
    })();
    // 最终去重：中英文名都保证唯一（中文用三字名/中间首字母，英文加首字母）
    (function dedupeNpcNames(){
      const zhSeen=new Set(), enSeen=new Set();
      for(const pl of Object.values(state.players)){
        if(!pl.isRealPlayer)continue;
        zhSeen.add(String(pl.name||''));
        enSeen.add(String(pl.nameEn||'').toLowerCase());
      }
      const INIT='ABCDEFGHIJKLMNOPQRSTUVWXYZ';
      for(const pl of Object.values(state.players)){
        if(pl.isRealPlayer)continue;
        const country=pl.nationality||'法国';
        const cjk=country==='中国'||country==='日本'||country==='韩国';
        let zh=String(pl.name||''), en=String(pl.nameEn||'');
        let guard=0;
        while((zhSeen.has(zh)||(en&&enSeen.has(en.toLowerCase())))&&guard++<400){
          if(cjk){
            const base=zh.replace(/[·\s]/g,'').slice(0,2);
            const ch=String.fromCharCode(0x4e00+((hash(pl.id+guard))%6000));
            zh=base+ch;
          }else{
            const parts=zh.split('·');
            const g=parts[0]||'球员', sn=parts[parts.length-1]||'';
            zh=g+'·'+INIT[(hash(pl.id+guard))%26]+'·'+sn;
          }
          if(!en)en=zh;
          else if(guard>0){en=en.replace(/[A-Z]$/,'')+' '+INIT[guard%26]}
        }
        pl.name=zh;pl.nameZh=zh;
        if(!en||enSeen.has(en.toLowerCase()))en=en+' '+INIT[hash(pl.id)%26];
        pl.nameEn=en;
        zhSeen.add(zh);enSeen.add(en.toLowerCase());
      }
    })();

    if(state._usedPlayerNames)state._usedPlayerNames=null;
    PENDING_NAME_PLAYERS=[];USED_NAME_DIRTY=true;
    return {removedReal,renamed};
  }
  function dedupeRealPlayerIdentities(){
    // 以中文名为主键（同一人的中英文拼写可能不一致，中文名更稳定）
    const key=(pl)=>String(pl.name||pl.nameZh||pl.nameEn||'').trim();
    const groups=new Map();
    for(const pl of Object.values(state.players)){
      if(!pl.isRealPlayer||!pl.clubId)continue;
      const k=key(pl);if(!k)continue;
      if(!groups.has(k))groups.set(k,[]);
      groups.get(k).push(pl);
    }
    let removed=0;
    for(const list of groups.values()){
      if(list.length<2)continue;
      list.sort((a,b)=>{
        const ra=(state.clubs[a.clubId]?.management?.reputation)||0;
        const rb=(state.clubs[b.clubId]?.management?.reputation)||0;
        if(rb!==ra)return rb-ra;
        return (b.ca||0)-(a.ca||0);
      });
      for(const drop of list.slice(1)){
        const club=state.clubs[drop.clubId];
        if(club)club.playerIds=club.playerIds.filter(id=>id!==drop.id);
        state.freeAgents=(state.freeAgents||[]).filter(id=>id!==drop.id);
        for(const nt of Object.values(state.nationalTeams||{})){
          if(Array.isArray(nt.squadIds))nt.squadIds=nt.squadIds.filter(id=>id!==drop.id);
        }
        delete state.players[drop.id];
        forgetPlayerNumericId(drop.id);
        markUsedNameSetDirty();
        removed++;
      }
    }
    return removed;
  }
  function ensureUniquePlayerNames(){finalizeWorldNames();}


  function countryProfile(nationality){return COUNTRY_PROFILES[nationality]||{name:nationality||'未知国家',style:'综合型',focus:{speed:1,shooting:1,passing:1,control:1,defense:1,stamina:1}}}

