  // ── 扩展数据包（中超 / J1 / K联赛 / 沙特联）──────────────────────────────
  // 由外部脚本在加载 world.js 之前写入 globalThis.__FW_EXTEND__，
  // 让终端版与浏览器版共用同一套引擎，而不必把上千名球员硬编码进球文件。
  const EXT_DATA=(()=>{try{return (typeof globalThis!=='undefined'&&globalThis.__FW_EXTEND__)||null}catch(e){return null}})();
  const EUROPE_COUNTRIES=['英格兰','西班牙','法国','意大利','德国','荷兰'];
  const EXT_STADIUMS=(EXT_DATA&&EXT_DATA.stadiums)||{};
  const EXT_COLORS=(EXT_DATA&&EXT_DATA.colors)||{};  // 队名 -> {primary,secondary}  // 队名 -> {stadium,capacity,city}
  const EXT_CLUBS={};      // 队名 -> 扩展俱乐部元数据
  const EXT_SQUADS={};     // 队名 -> 球员数组
  const AFC_COUNTRIES=[];  // 使用亚足联赛制的国家
  if(EXT_DATA&&Array.isArray(EXT_DATA.packs)){
    for(const pack of EXT_DATA.packs){
      const c=pack.country;
      if(!c)continue;
      // 欧洲赛区的扩展联赛进欧战，其余默认亚足联
      if(pack.region==='europe'){
        if(!EUROPE_COUNTRIES.includes(c))EUROPE_COUNTRIES.push(c);
      }else if(!pack.region||pack.region==='asia'){
        AFC_COUNTRIES.push(c);
      }
      COUNTRY_PROFILES[c]={name:(c+'足球'),style:pack.style||'综合',focus:pack.focus||{speed:1,shooting:1,passing:1,control:1,defense:1,stamina:1}};
      const countryKeys=Object.keys(COUNTRY_SYSTEM);
      COUNTRY_SYSTEM[c]={id:'CT'+(20+countryKeys.length),name:c,federation:{id:'FA'+(30+countryKeys.length),name:(pack.federation&&pack.federation.name)||pack.federation||(c+'足球协会'),reputation:(pack.federation&&pack.federation.reputation)||pack.federationReputation||72},leagueFocus:pack.style||'综合'};
      for(const lg of (pack.leagues||[])){
        const code=lg.code;
        if(!LEAGUES.some(x=>x[1]===code))LEAGUES.push([lg.name,code,c]);
        LEAGUE_SHORT[code]=lg.short||lg.name;
        REAL_CLUBS[code]=(lg.clubs||[]).map(x=>x.name);
        SECOND_TIERS[code]=(lg.secondTierNames||[]);
        THIRD_TIERS[code]=[];
        for(const club of (lg.clubs||[])){
          EXT_CLUBS[club.name]=club;
          if(Array.isArray(club.players)&&club.players.length)EXT_SQUADS[club.name]=club.players;
        }
      }
    }
  }
