  function initNationalTeams(){
    state.nationalTeams={};
    const allNations=Object.keys(COUNTRY_SYSTEM).concat(EXTRA_NATIONS.map(x=>x.name).filter(n=>!COUNTRY_SYSTEM[n]));
    for(const key of allNations){
      const sys=COUNTRY_SYSTEM[key];
      state.nationalTeams[key]={id:'NT-'+(sys?sys.id:'CTX'+hash(key)),name:key+'国家队',countryId:key,coach:{name:key+'国家队主教练',trust:60,style:key==='西班牙'?'传控':key==='法国'?'攻守平衡':key==='巴西'?'进攻':key==='日本'?'纪律':'平衡'},squadIds:[],caps:0,wins:0,draws:0,losses:0,goalsFor:0,goalsAgainst:0,nextCallupDate:null,nextMatchDate:null,fixtures:[],tournament:{name:'国家队国际窗口',stage:'小组赛'}};
    }
  }
  // 没有本国联赛的国家：生成一批只属于国家队的球员
  let nextNationId=0;
  function ensureNationSquads(){
    const strengthOf=(n)=>{const e=EXTRA_NATIONS.find(x=>x.name===n);return e?e.strength:66};
    if(!nextNationId){let m=0;for(const k of Object.keys(state.players)){const n=parseInt(String(k).slice(1),10);if(Number.isFinite(n)&&n>m)m=n}nextNationId=m+1}
    for(const name of Object.keys(state.nationalTeams)){
      if(COUNTRY_SYSTEM[name])continue; // 有联赛的国家用俱乐部球员
      const existing=Object.values(state.players).filter(x=>x.nationality===name&&x.careerLifecycle?.status!=='retired').length;
      if(existing>=20)continue;
      const base=strengthOf(name);
      const need=23-existing;
      for(let i=0;i<need;i++){
        const r=rnd(hash('NATION-'+name+'-'+i));
        const pos=POS[i%POS.length];
        const ca=Math.max(45,Math.min(86,Math.round(base-6+r()*12)));
        const id='N'+(nextNationId++);
        const pool=(typeof NAME_PARTS!=='undefined'&&NAME_PARTS[name])||(typeof GENERATED_NAME_PARTS!=='undefined'&&GENERATED_NAME_PARTS[Math.floor(r()*GENERATED_NAME_PARTS.length)])||[['球员'],['一号']];
        const given=pool[0][Math.floor(r()*pool[0].length)]||'球员';
        const surname=(pool[1]&&pool[1][Math.floor(r()*pool[1].length)])||'';
        const full=name+'·'+surname+given;
        const pl={
          id,name:full,nameEn:'',nameZh:full,
          realPlayerId:null,isRealPlayer:false,isNpc:true,nationOnly:true,
          age:23+Math.floor(r()*10),position:pos,nationality:name,clubId:null,
          ca,pa:Math.min(92,ca+4+Math.floor(r()*10)),
          stats:buildStatsFromCA(ca,pos,hash(id)),marketValue:600000,
          fitness:100,morale:72,fatigue:0,
          contract:null,development:{coachTrust:50,role:'regular'},seasonStats:{appearances:0,goals:0,assists:0,minutes:0,avgRating:0},growthHistory:[],matchHistory:[]
        };
        state.players[id]=pl;
        notePlayerNumericId(id);
        if(state.dataRegistry&&state.dataRegistry.players)state.dataRegistry.players[id]=pl;
      }
    }
  }
  function nationalTeamForPlayer(p){return p?.nationality?state.nationalTeams[p.nationality]||null:null}
  function nationalPlayerEligible(p){
    if(!p||p.age<18||p.careerLifecycle?.status==='retired')return false;
    if(isInjured(p))return false;
    const apps=p.seasonStats?.appearances||0, role=p.development?.role;
    return (p.ca||0)>=70 || ((p.ca||0)>=66 && (apps>=5 || role==='regular' || role==='key player'));
  }
  // 国家队入选评估：排名、评分、入选线、队长
  // 六维基准对比（放射图数据）
  function attributeBenchmark(p){
    if(!p||!p.stats)return null;
    const keys=['speed','shooting','passing','control','defense','stamina'];
    const avg=(list)=>{
      const out={};
      for(const k of keys){
        let sum=0,n=0;
        for(const x of list){const v=x&&x.stats?x.stats[k]:null;if(typeof v==='number'){sum+=v;n++}}
        out[k]=n?sum/n:0;
      }
      return out;
    };
    const club=state.clubs[p.clubId];
    const squad=(club?club.playerIds:[]).map(id=>state.players[id]).filter(Boolean).filter(x=>x.id!==p.id);
    const lg=club?state.leagues.find(l=>l.id===club.leagueId):null;
    const league=squad.concat((lg?lg.clubIds:[]).flatMap(cid=>((state.clubs[cid]||{}).playerIds||[]).map(id=>state.players[id]).filter(Boolean))).slice(0,600);
    const samePos=squad.filter(x=>x.position===p.position);
    const self={};for(const k of keys)self[k]=(p.stats&&p.stats[k])||0;
    const squadAvg=avg(squad), leagueAvg=avg(league), posAvg=avg(samePos);
    // 训练建议：与自己位置平均差距最大的一项
    let worstKey=null,worstGap=0;
    for(const k of keys){
      const gap=(posAvg[k]||0)-self[k];
      if(gap>worstGap){worstGap=gap;worstKey=k}
    }
    return {keys,self,squadAvg,leagueAvg,posAvg,weakKey:worstKey,weakGap:Math.round(worstGap*10)/10,squadSize:squad.length};
  }
  function nationalSelection(p){
    if(!p||!p.nationality)return null;
    const nt=state.nationalTeams[p.nationality];
    if(!nt)return null;
    const score=(x)=>((x.ca||0)*0.72)+((x.seasonStats?.avgRating||6.6)*4)+((x.seasonStats?.appearances||0)*0.15)+(x.fitness||70)*0.08-(x.fatigue||0)*0.10;
    const pool=Object.values(state.players).filter(x=>x.nationality===p.nationality&&x.age>=18&&x.careerLifecycle?.status!=='retired');
    const ranked=pool.slice().sort((a,b)=>score(b)-score(a));
    const rank=ranked.findIndex(x=>x.id===p.id)+1;
    const cutoff=ranked[22]?score(ranked[22]):0;
    const myScore=score(p);
    const inSquad=(nt.squadIds||[]).includes(p.id);
    const samePos=ranked.filter(x=>x.position===p.position);
    const posRank=samePos.findIndex(x=>x.id===p.id)+1;
    let reason='';
    if(rank<0)reason='暂未进入国家队视野';
    else if(myScore>=cutoff&&inSquad)reason='能力与状态达到国家队标准';
    else if(myScore>=cutoff)reason='达到入选线，等待本期名单公布';
    else if(myScore>=cutoff-6)reason='接近入选线，需要更多高水平比赛表现';
    else reason='与国家队主力仍有差距，建议先在俱乐部站稳位置';
    if(posRank<=3&&samePos.length>3)reason+=' · 同位置竞争排名第 '+posRank;
    return {rank,total:ranked.length,myScore:Math.round(myScore*10)/10,cutoff:Math.round(cutoff*10)/10,inSquad,selected:rank>0&&rank<=23,posRank,posCount:samePos.length,reason,captain:nt.captain||null,nextMatchDate:nt.nextMatchDate||null,nextCallupDate:nt.nextCallupDate||null};
  }
  function refreshNationalCallups(date=state.date){
    if(!Object.keys(state.nationalTeams).length)initNationalTeams();
    for(const [country,nt] of Object.entries(state.nationalTeams)){
      const pool=Object.values(state.players).filter(p=>p.nationality===country&&p.age>=18&&p.careerLifecycle?.status!=='retired'&&!isInjured(p));
      const eligible=pool.sort((a,b)=>((b.ca||0)-(a.ca||0))+(((b.seasonStats?.appearances||0)-(a.seasonStats?.appearances||0))*0.2)).slice(0,23);
      if(state.player && state.player.nationality===country && nationalPlayerEligible(state.player)){
        const p=state.player;
        if(!p.nationalTeam)p.nationalTeam={caps:0,starts:0,goals:0,assists:0,callups:0,debuts:0,history:[],consent:'pending',invitation:null};
        if(!p.nationalTeam.consent)p.nationalTeam.consent='pending';
        if(p.nationalTeam.consent!=='accepted' && !p.nationalTeam.invitation){
          p.nationalTeam.consent='pending';
          p.nationalTeam.invitation={date,status:'pending',country};
        }
        if(p.nationalTeam.consent==='accepted' && !eligible.some(x=>x.id==='PUSER')){
          eligible.pop(); eligible.push(p); eligible.sort((a,b)=>((b.ca||0)-(a.ca||0))+(((b.seasonStats?.appearances||0)-(a.seasonStats?.appearances||0))*0.2));
        }
      }
      nt.squadIds=eligible.map(p=>p.id);
      // 队长：队内能力最高、年龄最大者
      const cap=eligible.slice().sort((a,b)=>((b.ca||0)-(a.ca||0))||((b.age||0)-(a.age||0)))[0];
      if(cap)nt.captain={id:cap.id,name:cap.name,ca:Math.round(cap.ca)};
      nt.squadMeta={date,size:eligible.length,avgCA:Math.round(eligible.reduce((a,x)=>a+(x.ca||0),0)/Math.max(1,eligible.length))};
      // 玩家首次入选：写一条国家队消息
      if(state.player&&state.player.nationality===country&&eligible.some(x=>x.id==='PUSER')){
        const pl=state.player;
        if(!pl.nationalTeam)pl.nationalTeam={caps:0,starts:0,goals:0,assists:0,callups:0,debuts:0,history:[],consent:'pending',invitation:null};
        pl.nationalTeam.callups=(pl.nationalTeam.callups||0)+1;
        pl.nationalTeam.lastCallup={date,country,squadSize:eligible.length};
        pushMedia(pl,'入选国家队大名单',`你入选了 ${country} 国家队本期 ${eligible.length} 人名单，集训即将开始。`,'good');
        addWorldEvent('national','入选国家队',`${pl.name} 入选 ${country} 国家队本期名单。`,date,'career');
      }
      for(const nt2 of [nt]){nt2.squadIds=(nt2.squadIds||[]).filter(id=>{const pl=state.players[id];return pl&&pl.careerLifecycle?.status!=='retired'})}
      nt.nextCallupDate=addDays(date,90);
      for(const pid of nt.squadIds){const p=state.players[pid];initDevelopment(p,hash(pid));if(!p.nationalTeam)p.nationalTeam={caps:0,starts:0,goals:0,assists:0,callups:0,debuts:0,history:[]};p.nationalTeam.callups++;if(p.id==='PUSER')p.nationalTeam.lastCallupDate=date;}
    }
  }
  function setNationalConsent(consent){
    const p=state.player;if(!p||!p.nationality)return {ok:false,reason:'no-player'};
    const inv=p.nationalTeam&&p.nationalTeam.invitation;
    if(!inv||inv.status!=='pending')return {ok:false,reason:'no-invitation'};
    if(isInjured(p))return {ok:false,reason:'injured'};
    if(!p.nationalTeam)p.nationalTeam={caps:0,starts:0,goals:0,assists:0,callups:0,debuts:0,history:[]};
    p.nationalTeam.consent=consent==='accepted'?'accepted':'declined';
    p.nationalTeam.invitation=null;
    const nt=nationalTeamForPlayer(p);
    if(nt){
      if(p.nationalTeam.consent==='accepted')refreshNationalCallups(state.date);
      else nt.squadIds=nt.squadIds.filter(id=>id!=='PUSER');
    }
    return {ok:true,accepted:p.nationalTeam.consent==='accepted'};
  }
  function nationalRankScore(country){
    const nt=state.nationalTeams[country]; if(!nt)return 0;
    return Math.round(1500 + nationalStrength(country)*8 + (nt.wins||0)*12 - (nt.losses||0)*8);
  }
  function refreshNationalRanking(){
    state.nationalRanking=Object.keys(state.nationalTeams).map(country=>({country,score:nationalRankScore(country),teamId:state.nationalTeams[country].id})).sort((a,b)=>b.score-a.score).map((x,i)=>({...x,rank:i+1}));
  }
  // 大洲归属
  const CONMEBOL_NATIONS=['巴西','阿根廷','乌拉圭','哥伦比亚','智利','厄瓜多尔','秘鲁','巴拉圭','委内瑞拉','玻利维亚'];
  const CONCACAF_NATIONS=['美国','墨西哥','加拿大','哥斯达黎加','牙买加','巴拿马','洪都拉斯'];
  const CAF_NATIONS=['摩洛哥','塞内加尔','尼日利亚','埃及','阿尔及利亚','科特迪瓦','喀麦隆','加纳','突尼斯','马里','南非','安哥拉'];
  function confOf(country){
    const extra=typeof EXTRA_NATIONS!=='undefined'?EXTRA_NATIONS.find(x=>x.name===country):null;
    if(extra&&extra.conf)return extra.conf;
    if(EUROPE_COUNTRIES.includes(country)||['塞尔维亚','苏格兰','土耳其','捷克','克罗地亚','奥地利','挪威','瑞典','希腊','比利时','瑞士','丹麦','葡萄牙'].includes(country))return 'uefa';
    if(AFC_COUNTRIES.includes(country))return 'afc';
    if(CONMEBOL_NATIONS.includes(country))return 'conmebol';
    if(CONCACAF_NATIONS.includes(country))return 'concacaf';
    if(CAF_NATIONS.includes(country))return 'caf';
    return 'uefa';
  }
  function tournamentCountries(type){
    const all=Object.keys(state.nationalTeams).filter(c=>(state.nationalTeams[c].squadIds||[]).length>0);
    const pool=all.length?all:Object.keys(state.nationalTeams);
    const byStrength=pool.slice().sort((x,y)=>nationalStrength(y)-nationalStrength(x));
    const take=(list,n)=>list.slice(0,n);
    if(type==='WORLD')return take(byStrength,48);
    if(type==='EURO')return take(byStrength.filter(c=>confOf(c)==='uefa'),24);
    if(type==='ASIAN')return take(byStrength.filter(c=>confOf(c)==='afc'),24);
    if(type==='COPA')return take(byStrength.filter(c=>confOf(c)==='conmebol'||confOf(c)==='concacaf'),16);
    if(type==='AFRICA')return take(byStrength.filter(c=>confOf(c)==='caf'),24);
    return take(byStrength,16);
  }
  // 依据大洲与赛事规模分组 + 淘汰赛
  function createNationalTournament(type,name,date){
    const countries=tournamentCountries(type);
    const t={id:`NT-${type}-${state.season}`,type,name,season:state.season,startDate:date,status:'completed',countryIds:countries,groups:[],results:[],champion:null};
    const strength=c=>nationalStrength(c);
    const play=(x,y,stage,seed)=>{
      const r=rnd(hash(seed+x+y)),a=strength(x),b=strength(y);
      let sa=Math.max(0,Math.min(4,Math.round(0.9+(a-b)/16+r()*2)));
      let sb=Math.max(0,Math.min(4,Math.round(0.8+(b-a)/16+r()*2)));
      let pens=null,soWinner=null;
      if(sa===sb&&stage!=='group'){
        // 淘汰赛平局 → 点球大战（国家队没有射手属性，用国家队实力差换算命中率）
        const pH=clamp(0.76+(a-b)/120,0.62,0.90),pA=clamp(0.76+(b-a)/120,0.62,0.90);
        const first=r()<0.5?'home':'away';
        const so=shootoutCore(first,(team)=>r()<(team==='home'?pH:pA));
        pens={home:so.home,away:so.away};
        soWinner=so.winner;
      }
      const winner=sa>sb?x:sb>sa?y:(soWinner==='home'?x:soWinner==='away'?y:(r()<0.5?x:y));
      const res={stage,homeCountry:x,awayCountry:y,score:{home:sa,away:sb},pens,winner};
      t.results.push(res);
      return res;
    };
    // 分组：每组 4 队
    const groupSize=4;
    const groupCount=Math.max(1,Math.floor(countries.length/groupSize));
    const groups=[];
    for(let g=0;g<groupCount;g++)groups.push([]);
    countries.forEach((c,i)=>groups[i%groupCount].push(c));
    groups.forEach((g,gi)=>{
      const table=g.map(c=>({country:c,p:0,w:0,d:0,l:0,gf:0,ga:0,pts:0}));
      const idx=Object.fromEntries(table.map(r=>[r.country,r]));
      for(let i=0;i<g.length;i++)for(let j=i+1;j<g.length;j++){
        const x=g[i],y=g[j];
        const r=rnd(hash(type+'G'+gi+x+y+date));
        const a=strength(x),b=strength(y);
        const sa=Math.max(0,Math.min(4,Math.round(0.9+(a-b)/16+r()*2)));
        const sb=Math.max(0,Math.min(4,Math.round(0.8+(b-a)/16+r()*2)));
        t.results.push({stage:'group',group:gi,homeCountry:x,awayCountry:y,score:{home:sa,away:sb},winner:sa>sb?x:sb>sa?y:null});
        idx[x].p++;idx[y].p++;idx[x].gf+=sa;idx[x].ga+=sb;idx[y].gf+=sb;idx[y].ga+=sa;
        if(sa>sb){idx[x].w++;idx[x].pts+=3;idx[y].l++}
        else if(sb>sa){idx[y].w++;idx[y].pts+=3;idx[x].l++}
        else{idx[x].d++;idx[y].d++;idx[x].pts++;idx[y].pts++}
      }
      table.sort((m,n)=>(n.pts-m.pts)||((n.gf-n.ga)-(m.gf-m.ga))||(n.gf-m.gf));
      t.groups.push({name:'小组 '+(gi+1),table});
    });
    // 出线：各组前二 + 成绩最好的第三名
    const winners=t.groups.map(g=>g.table[0].country);
    const runners=t.groups.map(g=>g.table[1].country);
    const thirds=t.groups.map(g=>g.table[2]).filter(Boolean).sort((m,n)=>(n.pts-m.pts)||((n.gf-n.ga)-(m.gf-m.ga))).map(x=>x.country);
    let qualified=[...winners,...runners];
    const target=t.groups.length===12?32:t.groups.length>=6?16:t.groups.length*2;
    while(qualified.length<target&&thirds.length)qualified.push(thirds.shift());
    qualified=qualified.slice(0,target);
    // 淘汰赛
    let seeds=qualified.slice().sort((x,y)=>strength(y)-strength(x));
    let roundName=seeds.length>=32?'1/16 决赛':seeds.length>=16?'1/8 决赛':seeds.length>=8?'1/4 决赛':'半决赛';
    let guard=0;
    while(seeds.length>1&&guard++<6){
      const winnersNext=[];
      for(let i=0;i<seeds.length/2;i++){
        const x=seeds[i],y=seeds[seeds.length-1-i];
        if(!x||!y){winnersNext.push(x||y);continue}
        winnersNext.push(play(x,y,roundName,type+'K'+i).winner);
      }
      seeds=winnersNext;
      roundName=seeds.length>=16?'1/8 决赛':seeds.length>=8?'1/4 决赛':seeds.length>=4?'半决赛':'决赛';
    }
    t.champion=seeds[0]||null;
    // 玩家所在国家队参与时，结算其国家队数据
    const me=state.player;
    if(me&&me.nationality&&countries.includes(me.nationality)&&(state.nationalTeams[me.nationality]?.squadIds||[]).includes(me.id)){
      const played=t.results.filter(r=>r.homeCountry===me.nationality||r.awayCountry===me.nationality);
      if(!me.nationalTeam)me.nationalTeam={caps:0,starts:0,goals:0,assists:0,callups:0,debuts:0,history:[],consent:'accepted'};
      played.forEach(r=>{
        const rr=rnd(hash('PLTOUR'+r.homeCountry+r.awayCountry+date));
        const isHome=r.homeCountry===me.nationality;
        const gf=isHome?r.score.home:r.score.away;
        const goals=gf>0&&rr()<0.45?1:0;
        me.nationalTeam.caps++;me.nationalTeam.starts++;
        me.nationalTeam.goals+=goals;
        me.nationalTeam.history.push({date,opponent:isHome?r.awayCountry:r.homeCountry,goals,assists:0,started:true,minutes:90,tournament:t.name,stage:r.stage});
        if(me.nationalTeam.history.length>40)me.nationalTeam.history.shift();
      });
      if(t.champion===me.nationality){
        addWorldEvent('national','国家队夺冠',`${me.nationality} 夺得 ${state.season} ${name}冠军！`,state.date,'career');
      }
    }
    state.nationalTournaments.push(t);
    t.competitionId='NT-'+t.type;
    t.matchesCount=(t.results||[]).length;
    // 把淘汰赛结果也写入 state.matches，便于统一查看
    for(const r of (t.results||[])){
      if(r.stage==='group')continue;
      state.matches.push({
        id:'NTM-'+t.type+'-'+t.season+'-'+state.matches.length,
        date:t.startDate,season:t.season,leagueId:null,
        competitionId:'NT-'+t.type,competition:t.name,
        homeCountry:r.homeCountry,awayCountry:r.awayCountry,
        score:r.score,status:'completed',events:[],national:true,
        stage:r.stage
      });
    }
    if(state.matches.length>6000)state.matches.shift();
    if(t.champion&&t.champion!==(me&&me.nationality)){
      addWorldEvent('national',name+'冠军',`${t.champion} 夺得 ${state.season} ${name}冠军。`,state.date,'national');
    }
    return t;
  }
  // 国家队赛事赛历：世界杯 / 欧洲杯 / 亚洲杯 / 非洲杯 / 美洲杯
  function processNationalTournaments(date){
    refreshNationalRanking();
    const year=Number(date.slice(0,4));
    const md=date.slice(5,10);
    const has=(type)=>state.nationalTournaments.some(t=>t.type===type&&t.season===state.season);
    if((year-2026)%4===0 && md>='06-01' && md<='06-30' && !has('WORLD')) createNationalTournament('WORLD','世界杯',year+'-06-01');
    if((year-2028)%4===0 && md>='06-01' && md<='07-15' && !has('EURO')) createNationalTournament('EURO','欧洲杯',year+'-06-01');
    if((year-2027)%4===0 && md>='01-05' && md<='02-10' && !has('ASIAN')) createNationalTournament('ASIAN','亚洲杯',year+'-01-10');
    if(year%2===1 && md>='01-10' && md<='02-15' && !has('AFRICA')) createNationalTournament('AFRICA','非洲杯',year+'-01-15');
    if(year%2===0 && md>='06-10' && md<='07-10' && !has('COPA')) createNationalTournament('COPA','美洲杯',year+'-06-15');
  }
  function nationalStrength(country){const nt=state.nationalTeams[country];if(!nt||!nt.squadIds.length)return 50;let sum=0,n=0;for(const pid of nt.squadIds){const p=state.players[pid];if(p){sum+=p.ca;n++}}return n?sum/n:50}
  function simulateNationalMatch(nt,date){
    const countries=Object.keys(state.nationalTeams).filter(x=>x!==nt.countryId); if(!countries.length)return null;
    const opponent=countries[hash(nt.countryId+date)%countries.length], r=rnd(hash('NT'+nt.countryId+opponent+date));
    const a=nationalStrength(nt.countryId),b=nationalStrength(opponent);
    const home=a>=b, homeScore=Math.max(0,Math.min(4,Math.round(0.7+(a-b)/15+r()*2))), awayScore=Math.max(0,Math.min(4,Math.round(0.6+(b-a)/15+r()*2)));
    const score=home?{home:homeScore,away:awayScore}:{home:awayScore,away:homeScore};
    const ntGoals=home?score.home:score.away, oppGoals=home?score.away:score.home;
    nt.caps++;nt.goalsFor+=ntGoals;nt.goalsAgainst+=oppGoals;if(ntGoals>oppGoals)nt.wins++;else if(ntGoals===oppGoals)nt.draws++;else nt.losses++;
    const match={id:'NTM-'+nt.countryId+'-'+date,date,countryId:nt.countryId,opponent,score,homeCountry:home?nt.countryId:opponent,awayCountry:home?opponent:nt.countryId,type:'international-window',tournament:'国家队国际窗口'};
    nt.fixtures.push(match); if(nt.fixtures.length>20)nt.fixtures.shift(); state.nationalEvents.push(match);if(state.nationalEvents.length>40)state.nationalEvents.shift();
    // 接入比赛中心：国家队比赛也进 state.matches
    const rec={id:match.id,fixtureId:null,date,season:state.season,leagueId:null,
      competitionId:'NT',competition:match.tournament||'国家队国际比赛',
      homeClubId:null,awayClubId:null,
      homeCountry:match.homeCountry,awayCountry:match.awayCountry,
      score:match.score,status:'completed',events:[],stats:null,
      evaluation:{home:match.homeCountry,away:match.awayCountry},
      national:true};
    state.matches.push(rec);
    if(state.matches.length>4000)state.matches.shift();
    const squad=nt.squadIds.map(id=>state.players[id]).filter(Boolean);
    const ranked=squad.slice().sort((a,b)=>{
      const score=p=>((p.ca||0)*0.72)+((p.seasonStats?.avgRating||6.6)*4)+((p.seasonStats?.appearances||0)*0.15)+(p.fitness||70)*0.08-(p.fatigue||0)*0.10;
      return score(b)-score(a);
    });
    let selected=ranked.slice(0,18);
    if(state.player && state.player.nationality===nt.countryId && state.player.nationalTeam?.consent!=='accepted') selected=selected.filter(x=>x.id!=='PUSER');
    const starters=selected.slice(0,11);
    const goalWeights=selected.map(p=>{const pos=p.position||'CM',attackPos=['ST','LW','RW','AM'].includes(pos);return Math.max(0.2,(p.stats?.shooting||p.ca||60)*0.75+(p.ca||60)*0.15+(attackPos?24:0)+(starters.includes(p)?8:0));});
    const goalRecipients=[];for(let g=0;g<ntGoals;g++){const total=goalWeights.reduce((a,b)=>a+b,0);let pick=r()*total,idx=0;for(let i=0;i<goalWeights.length;i++){pick-=goalWeights[i];if(pick<=0){idx=i;break;}}goalRecipients.push(idx);}
    selected.forEach((p,i)=>{
      if(!p.nationalTeam)p.nationalTeam={caps:0,starts:0,goals:0,assists:0,callups:0,debuts:0,history:[]};
      const started=i<11, minutes=started?(72+Math.floor(r()*19)):(18+Math.floor(r()*38));
      p.nationalTeam.caps++;if(started)p.nationalTeam.starts++;if(p.nationalTeam.caps===1)p.nationalTeam.debuts++;
      const goals=goalRecipients.filter(x=>x===i).length, pos=p.position||'CM',attackPos=['ST','LW','RW','AM'].includes(pos), assists=goals&&r()<(attackPos?0.34:0.20)?1:0;
      p.nationalTeam.goals+=goals;p.nationalTeam.assists+=assists;
      p.nationalTeam.history.push({date,opponent,goals,assists,started,minutes});if(p.nationalTeam.history.length>30)p.nationalTeam.history.shift();
    });
    nt.nextMatchDate=addDays(date,90);nt.nextCallupDate=addDays(date,90);refreshNationalRanking();return match;
  }
  function processNationalWindow(date){
    if(!Object.keys(state.nationalTeams).length)initNationalTeams();
    const teams=Object.values(state.nationalTeams), dueMatches=teams.filter(nt=>!nt.nextMatchDate||date>=nt.nextMatchDate).map(nt=>nt.countryId);
    if(teams.some(nt=>!nt.nextCallupDate||date>=nt.nextCallupDate))refreshNationalCallups(date);
    for(const nt of teams)if(dueMatches.includes(nt.countryId))simulateNationalMatch(nt,date);
    processNationalTournaments(date);
  }
  // 生涯纪录：转会轨迹、荣誉室、里程碑
  function careerRecords(p){
    if(!p)return null;
    const c=careerOf(p);
    const transfers=[];
    for(const g of (p.growthHistory||[])){
      if(g.type!=='transfer')continue;
      transfers.push({date:g.date,from:g.fromClubId||null,to:g.toClubId||null,fee:g.fee||0,type:g.transferType||'转会'});
    }
    for(const t of (c.transfers||[]))transfers.push(t);
    transfers.sort((a,b)=>String(a.date).localeCompare(String(b.date)));
    // 荣誉：联赛冠军/杯赛/洲际/个人奖项
    const honours=(p.honours||[]).map(h=>({season:h.season,type:h.type||'奖项',name:h.name||h.leagueName||'',clubId:h.clubId||null}));
    const tally={};
    for(const h of honours){const k=h.type;tally[k]=(tally[k]||0)+1}
    // 生涯效率
    const cs=p.careerStats||{};
    const per90=(v)=>cs.minutes?+(v/(cs.minutes/90)).toFixed(2):0;
    const clubs=[...new Set((p.seasonHistory||[]).flatMap(x=>x.clubIds||[]))];
    return {
      transfers,honours,tally,
      clubs:clubs.map(id=>({id,name:state.clubs[id]?state.clubs[id].name:''})),
      totals:{
        apps:cs.appearances||0,goals:cs.goals||0,assists:cs.assists||0,
        minutes:cs.minutes||0,seasons:(p.seasonHistory||[]).length,
        goalsPer90:per90(cs.goals||0),assistsPer90:per90(cs.assists||0),
        honoursTotal:honours.length
      }
    };
  }
  function careerStage(p){
    const age=Number(p?.age||18);
    if(age<16)return 'youth';
    if(age<18)return 'academy';
    if(age<23)return 'early-career';
    if(age<29)return 'prime';
    if(age<33)return 'late-prime';
    if(age<36)return 'veteran';
    return 'retirement-window';
  }
  function ensureCareerLifecycle(p){
    if(!p)return;
    if(!p.careerLifecycle)p.careerLifecycle={stage:careerStage(p),status:'active',debutDate:null,retirementAge:34};
    if(!p.careerLifecycle.retirementAge)p.careerLifecycle.retirementAge=34;
    p.careerLifecycle.stage=careerStage(p);
    if(p.careerLifecycle.status!=='retired'){
      p.careerLifecycle.status=p.age>=p.careerLifecycle.retirementAge?'retirement-window':'active';
    }
    if(!p.careerLifecycle.debutDate&&p.age>=18)p.careerLifecycle.debutDate=p.birthDate?addDays(p.birthDate,Math.max(0,Math.round((18-(Number(p.age)||18))*365.25))):state.date;
  }
  function processNpcRetirement(p,date=state.date){
    if(!p||p.id==='PUSER'||p.careerLifecycle?.status==='retired') return false;
    initDevelopment(p,hash(p.id));
    const age=Number(p.age||18), ca=Number(p.ca||0), pos=p.position||'CM';
    let retirementAge=36;
    if(pos==='GK') retirementAge=38;
    else if(pos==='CB') retirementAge=37;
    if(ca>=82) retirementAge+=1;
    if(ca>=90 && (pos==='GK'||pos==='CB')) retirementAge+=1;
    retirementAge=clamp(retirementAge,35,40);
    p.careerLifecycle=p.careerLifecycle||{};
    p.careerLifecycle.retirementAge=retirementAge;
    p.careerLifecycle.stage=careerStage(p);
    if(age>=retirementAge || age>=40){
      const oldClub=state.clubs[p.clubId];
      if(oldClub) oldClub.playerIds=oldClub.playerIds.filter(id=>id!==p.id);
      state.freeAgents=(state.freeAgents||[]).filter(id=>id!==p.id);
      p.clubId=null; p.contract=null; p.loan=null; p.transferOffers=[];
      p.careerLifecycle.status='retired'; p.careerLifecycle.retiredDate=date;
      for(const nt of Object.values(state.nationalTeams||{})){if(Array.isArray(nt.squadIds)&&nt.squadIds.includes(p.id))nt.squadIds=nt.squadIds.filter(x=>x!==p.id)}
      recordPlayerTransfer(p,{date,type:'retirement',fromClubId:oldClub?.id||null,toClubId:null,fee:0});
      addWorldEvent('retirement','球员退役',`${p.name} 结束职业生涯，正式退役。`,date,'player');
      return true;
    }
    p.careerLifecycle.status=age>=retirementAge-2?'retirement-window':'active';
    return false;
  }
  function pruneRetiredPlayers(){
    const keepFrom=addDays(state.date,-400);
    let removed=0;
    for(const p of Object.values(state.players)){
      if(p.id==='PUSER')continue;
      if(p.careerLifecycle?.status!=='retired')continue;
      const d=p.careerLifecycle.retiredDate||'';
      if(d&&d<keepFrom){delete state.players[p.id];forgetPlayerNumericId(p.id);markUsedNameSetDirty();removed++}
    }
    return removed;
  }
  function processAllNpcRetirements(date=state.date){
    for(const p of Object.values(state.players)) if(p.id!=='PUSER') processNpcRetirement(p,date);
  }
  function syncPlayerAge(p){
    if(!p)return false;
    if(!p.birthDate){
      p.birthDate=addDays(state.date,-Math.round((Number(p.age)||18)*365.2425));
    }
    const birth=new Date(p.birthDate+'T00:00:00Z');
    const now=new Date(state.date+'T00:00:00Z');
    let age=now.getUTCFullYear()-birth.getUTCFullYear();
    const beforeBirthday=(now.getUTCMonth()<birth.getUTCMonth())||(now.getUTCMonth()===birth.getUTCMonth()&&now.getUTCDate()<birth.getUTCDate());
    if(beforeBirthday)age--;
    age=Math.max(0,age);
    const changed=age!==Number(p.age);
    p.age=age;
    ensureCareerLifecycle(p);
    return changed;
  }

  function initDevelopment(p,seed=1){
    if(!p.development)p.development={trainingResponse:0.75+((seed*37)%26)/100,professionalism:0.65+((seed*53)%31)/100,ambition:0.65+((seed*71)%31)/100,lastTrainingDate:null,lastNpcGrowthMonth:null,coachTrust:45,role:'rotation'};
    if(!p.development.coachCommunication)p.development.coachCommunication={successStreak:0,failStreak:0,total:0,accepted:0,rejected:0,lastType:null,lastDate:null,momentum:0};
    if(p.fitness==null)p.fitness=100;
    if(p.morale==null)p.morale=75;
    if(p.fatigue==null)p.fatigue=0;
    if(!p.growthHistory)p.growthHistory=[];
    if(!p.careerHistory)p.careerHistory=[];
    if(!p.transferHistory)p.transferHistory=[];
    if(!p.trainingProgress)p.trainingProgress={};
    for(const k of GROWTH_STATS) if(p.trainingProgress[k]==null) p.trainingProgress[k]=0;
    if(!p.matchHistory)p.matchHistory=[];
    if(!p.seasonStats)p.seasonStats={season:state.season||'2026/27',clubIds:p.clubId?[p.clubId]:[],appearances:0,starts:0,minutes:0,goals:0,assists:0,avgRating:0};
    if(!Array.isArray(p.seasonStats.clubIds))p.seasonStats.clubIds=p.clubId?[p.clubId]:[];
    if(!p.careerStats)p.careerStats={appearances:0,starts:0,minutes:0,goals:0,assists:0};
    if(!p.contract)p.contract={clubId:p.clubId,startDate:'2026-08-01',endDate:'2028-06-30',weeklyWage:800,role:'rotation'};
    if(!p.transferOffers)p.transferOffers=[];
    if(!p.relationships)p.relationships={coachTrust:45,teamChemistry:55,clubLoyalty:50,agentTrust:60,mediaReputation:50,fanSupport:55};
    if(p.marketValue==null)p.marketValue=calculateMarketValue(p);
    if(!p.marketValueHistory)p.marketValueHistory=[];
    ensureCareerLifecycle(p);
  }
  function calculateMarketValue(p){
    const ageFactor=p.age<=19?1.28:p.age<=21?1.18:p.age<=23?1.10:p.age<=26?1.04:p.age<=29?0.94:p.age<=32?0.72:0.48;
    const caFactor=Math.exp((clamp(Math.max(40,Number(p.ca)||50),40,95)-50)*0.163);
    const potentialGap=Math.max(0,p.pa-p.ca);
    const potentialFactor=1+Math.min(0.38,potentialGap/100*0.38);
    const appearances=p.seasonStats?.appearances||0;
    const avgRating=p.seasonStats?.avgRating||6;
    const formFactor=clamp(0.82+(avgRating-6)*0.18+Math.min(0.12,appearances/30*0.12),0.65,1.25);
    const contractYears=contractYearsLeft(p);
    const contractFactor=contractYears<=0?0.70:contractYears<1?0.82:contractYears<2?0.92:contractYears<3?1:1.06;
    const leagueId=p.clubId?state.clubs[p.clubId]?.leagueId:null;
    const leagueIndex=leagueId?Math.max(0,state.leagues.findIndex(l=>l.id===leagueId)):5;
    const leagueFactor=1+Math.max(0,5-leagueIndex)*0.055;
    const base=250000;
    const value=Math.round(base*caFactor*ageFactor*potentialFactor*formFactor*contractFactor*leagueFactor/50000)*50000;
    const potentialPremium=1+Math.min(0.35,((p.pa||0)-(p.ca||0))/60*(p.age<=23?1:0.45));
    const next=clamp(value*potentialPremium,60000,220000000);
    p.marketValue=next;
    return next;
  }
  function updatePlayerMarketValue(p){
    if(p&&p.id==='PUSER'){
      const e=relationshipEffects(p);
      const base=calculateMarketValue(p);
      p.marketValue=Math.max(1000,Math.round(base*(1+e.media*0.22)/1000)*1000);
      return p.marketValue;
    }
    const old=p.marketValue||0; const value=calculateMarketValue(p);
    if(!p.marketValueHistory)p.marketValueHistory=[];
    ensureCareerLifecycle(p);
    if(old!==value){
      p.marketValueHistory.push({date:state.date,value});
      if(p.marketValueHistory.length>24)p.marketValueHistory.shift();
    }
    return value;
  }

  function recalcCA(p,allowDecline=false){
    if(!p)return 0;
    const old=Number(p.ca)||1;
    // CA 是模拟世界的持久能力值。属性平均值只能作为训练方向参考，绝不能直接把 CA 拉到一个较低数字。
    // NPC 的赛季能力变化由 processNpcSeasonDevelopment 单独决定；这里仅服务于玩家训练/属性微调。
    const isMe=p.id==='PUSER';
    if(!isMe&&Number(p.pa||0)<old)p.pa=Math.min(99,old);
    const avg=GROWTH_STATS.reduce((sum,k)=>sum+(Number(p.stats?.[k])||0),0)/GROWTH_STATS.length;
    const calculated=clamp(Math.round(avg),1,99);
    let target=old;
    if(calculated>old)target=Math.min(old+0.35,calculated);
    // 即使调用方要求衰退，也不允许一次重算按属性均值把 CA 大幅拉低。
    // 真正的年龄衰退只通过赛季结算中的小额 delta 处理。
    target=clamp(target,1,isMe?99:Math.max(1,Number(p.pa)||99));
    if(isMe&&target>old)p.ca=+(old+Math.min(0.35,(target-old))).toFixed(2);
    else p.ca=+target.toFixed(2);
    return +(p.ca-old).toFixed(2);
  }
  // 玩家的成长上限由「初始能力 + 训练 + 比赛表现」共同决定，不再有固定潜力值
  function playerCeiling(p){
    const base=Number(p.startCA||p.ca||60);
    const pro=clamp(Number(p.development?.professionalism||0.5),0,1);
    const resp=clamp(Number(p.development?.trainingResponse||0.5),0,1);
    const mins=Number(p.seasonStats?.minutes||0);
    const rating=Number(p.seasonStats?.avgRating||6.4);
    const seasonBonus=clamp((mins/2400),0,1.15)*1.4;
    const perfBonus=clamp((rating-6.4)*3.2,-2.2,4.5);
    const caps=base+14+pro*6+resp*5+seasonBonus+perfBonus;
    return clamp(caps,base,99);
  }
  // 训练选项说明与预期收益
  const TRAINING_EFFECTS={
    '技术':{stats:['control','passing'],label:'技术',desc:'控球与传球，适合组织型中场和边路球员',fatigue:7,fitness:-4},
    '速度':{stats:['speed'],label:'速度',desc:'纯速度提升，适合边锋与反击型前锋，涨幅集中但收益明显',fatigue:8,fitness:-5},
    '射门':{stats:['shooting'],label:'射门',desc:'射门精度与力量，前锋最直接的涨分项',fatigue:7,fitness:-4},
    '战术':{stats:['control','defense'],label:'战术',desc:'位置感与防守站位，中场/后卫更实用',fatigue:6,fitness:-3},
    '身体':{stats:['stamina','defense'],label:'身体',desc:'体能与对抗，代价是更多疲劳消耗',fatigue:10,fitness:-6},
    '休息':{stats:[],label:'休息',desc:'不涨属性，恢复疲劳 18、体能 8、士气 2',fatigue:-18,fitness:8,morale:2}
  };
  // 潜力信息：区间、兑现度、是否「在轨道上」
  // 训练场成绩 → 属性微增（每天一次），把 3D 训练与生涯成长闭环
  function trainingGroundResult(res){
    const p=state.player;
    if(!p)return {ok:false,reason:'no-player'};
    initDevelopment(p,hash(p.id));
    const c=careerOf(p);
    if(p.development.lastTrainingGroundDate===state.date)return {ok:false,reason:'already-today'};
    const hits=Math.max(0,Number(res&&res.hits)||0);
    const shots=Math.max(0,Number(res&&res.shots)||0);
    const dist=Math.max(0,Number(res&&res.distance)||0);
    if(shots<=0&&dist<30)return {ok:false,reason:'too-little'};
    p.development.lastTrainingGroundDate=state.date;
    p.development.groundBonus=clamp(0.01+(hits?Math.max(0,Math.min(1,(Number(res&&res.hits)||0)/Math.max(1,Number(res&&res.shots)||1)))*0.03:0),0,0.05);
    const rate=shots?hits/shots:0;
    const gains={};
    const apply=(k,v)=>{ if(!v||v<=0)return; const before=p.stats[k]||0; p.stats[k]=clamp(before+v,1,99); gains[k]=+(p.stats[k]-before).toFixed(2); };
    // 命中率 → 射门；跑动距离 → 体能；两者都给一点控球
    apply('shooting', +(rate*0.34).toFixed(3));
    apply('stamina', +(Math.min(1,dist/600)*0.22).toFixed(3));
    apply('control', +(rate*0.12).toFixed(3));
    const oldCA=p.ca;
    const delta=recalcCA(p);
    updatePlayerMarketValue(p);
    if(p.growthHistory){
      p.growthHistory.push({date:state.date,type:'training-ground',caBefore:oldCA,caAfter:p.ca,gains});
      if(p.growthHistory.length>30)p.growthHistory.shift();
    }
    const note='训练场：命中 '+hits+'/'+shots+'，跑动 '+Math.round(dist)+' m';
    if(!c.pendingEvents.length&&typeof pushCareerEvent==='function')pushCareerEvent(p);
    return {ok:true,hits,shots,rate:+rate.toFixed(2),distance:Math.round(dist),gains,caDelta:delta,note};
  }
  function potentialInfo(p){
    if(!p)return null;
    const ca=Number(p.ca||0),pa=Math.max(ca,Number(p.pa||ca));
    const ss=p.seasonStats||{};
    const minutes=Number(ss.minutes||0);
    const expected=p.age<=20?900:p.age<=23?1800:p.age<=27?2400:2000;
    const exposure=clamp(minutes/expected,0.35,1.15);
    const gap=pa-ca;
    // 球探区间：随出场与赛季推进收窄
    const uncertainty=gap>12?4:gap>6?3:2;
    const seasons=Math.max(0,(p.seasonHistory||[]).length);
    const shrink=clamp(1-seasons*0.15-exposure*0.2,0.35,1);
    const spread=Math.round(uncertainty*shrink);
    const pct=Math.round(ca/Math.max(1,pa)*100);
    const ageFactor=p.age<=20?1.18:p.age<=23?1.08:p.age<=26?0.92:p.age<=29?0.65:0.38;
    const yearsLeft=Math.max(0.5,Math.min(12,(p.age<=23?20:26)-p.age));
    const perYear=Math.max(0.2,(gap/ Math.max(1,yearsLeft))*ageFactor*exposure);
    return {
      ca:Math.round(ca*10)/10,pa,low:Math.max(Math.round(ca),pa-spread),high:pa+spread,
      gap:Math.round(gap*10)/10,pct,exposure:Math.round(exposure*100)/100,
      onTrack:pct>=60||gap<=6,
      perYear:Math.round(perYear*10)/10,
      verdict:gap<=3?'已基本兑现潜力':pct>=80?'接近上限':pct>=55?'成长中':'仍有较大空间'
    };
  }
  function trainingPreview(p){
    if(!p)return null;
    initDevelopment(p,hash(p.id));
    const response=p.development.trainingResponse,pro=p.development.professionalism;
    const fatigueFactor=1-(p.fatigue||0)/180;
    const moraleFactor=0.88+(p.morale||75)/500;
    const ageFactor=p.age<=20?1.18:p.age<=23?1.08:p.age<=26?0.92:p.age<=29?0.65:0.38;
    const blocked=isInjured(p);
    return {
      injured:blocked?{name:p.injury.name,daysLeft:p.injury.daysLeft}:null,
      trainedToday:p.development.lastTrainingDate===state.date,
      fatigue:Math.round(p.fatigue||0),fitness:Math.round(p.fitness||0),morale:Math.round(p.morale||0),
      efficiency:Math.round((0.78+pro*0.22)*fatigueFactor*moraleFactor*ageFactor*response*100)/100,
      options:['技术','速度','射门','战术','身体','休息'].map(function(k){
        const e=TRAINING_EFFECTS[k];
        const culture=countryTrainingFactor(p,e.stats);
        let min=null,max=null;
        if(e.stats.length){
          const base=(0.08+0.20/2)*response*(0.78+pro*0.22)*fatigueFactor*moraleFactor*ageFactor*culture;
          min=+(base*0.88).toFixed(2);max=+(base*1.12).toFixed(2);
        }
        return {key:k,label:e.label,stats:e.stats,desc:e.desc,fatigue:e.fatigue,fitness:e.fitness,morale:e.morale||0,min,max};
      })
    };
  }
  function startTrainingPlan(type,days){
    const p=state.player;if(!p)return {ok:false,reason:'no-player'};
    const valid=['技术','速度','射门','战术','身体','休息'];
    if(!valid.includes(type))return {ok:false,reason:'invalid-type'};
    const d=Math.max(1,Math.min(90,Number(days)||7));
    state.trainingPlan={type,days:d,startDate:state.date,endDate:addDays(state.date,d),trainedDays:0,skippedMatchDays:0,gains:{}};
    return {ok:true,plan:state.trainingPlan};
  }
  function stopTrainingPlan(){
    state.trainingPlan=null;
    return {ok:true};
  }
  function processTrainingPlan(targetDate){
    const plan=state.trainingPlan,p=state.player;
    if(!plan||!p)return;
    const end=plan.endDate;
    let cursor=addDays(state.date,1);
    while(cursor<=targetDate&&cursor<=end){
      const hasMatch=state.fixtures.some(f=>f.status==='scheduled'&&f.date===cursor&&(f.homeClubId===p.clubId||f.awayClubId===p.clubId));
      if(hasMatch){plan.skippedMatchDays=(plan.skippedMatchDays||0)+1;}
      else{
        const oldDate=state.date;state.date=cursor;
        const r=trainPlayer(plan.type);
        state.date=oldDate;
        if(r.ok){plan.trainedDays=(plan.trainedDays||0)+1;for(const [k,v] of Object.entries(r.gains||{}))plan.gains[k]=+( (plan.gains[k]||0)+v ).toFixed(2);}
      }
      cursor=addDays(cursor,1);
    }
    if(targetDate>=end){state.trainingPlan=null;}
  }

  function trainPlayer(type){
    const p=state.player;if(!p)return {ok:false,reason:'no-player'};
    initDevelopment(p,hash(p.id));
    if(p.development.lastTrainingDate===state.date)return {ok:false,reason:'already-trained'};
    if(isInjured(p)&&type!=='休息'){p.injury.daysLeft=Math.max(1,p.injury.daysLeft-1);return {ok:false,reason:'injured',injury:p.injury.name,daysLeft:p.injury.daysLeft}}
    const response=p.development.trainingResponse,pro=p.development.professionalism;
    if(type==='休息'){const f0=p.fatigue||0,fi0=p.fitness||0,m0=p.morale||0;p.fatigue=clamp(p.fatigue-18,0,100);p.fitness=clamp(p.fitness+8,0,100);p.morale=clamp(p.morale+2,0,100);p.development.lastTrainingDate=state.date;return {ok:true,gains:{},caDelta:0,type,status:{fatigue:Math.round(p.fatigue-f0),fitness:Math.round(p.fitness-fi0),morale:Math.round(p.morale-m0)}}}
    const fatigueFactor=1-p.fatigue/180;
    const moraleFactor=0.88+p.morale/500;
    const ageFactor=p.age<=20?1.18:p.age<=23?1.08:p.age<=26?0.92:p.age<=29?0.65:0.38;
    // 潜力余量越大成长越快，接近上限自然收敛
    // 成长曲线：离天花板越近越慢，但没有硬上限；训练投入与比赛表现决定天花板位置
    const ceiling=(p.id==='PUSER')?playerCeiling(p):Math.max(Number(p.pa||p.ca||60),Number(p.ca||60));
    const potentialGap=Math.max(0,ceiling-(p.ca||60));
    const potentialFactor=0.42+0.58*(1-Math.exp(-potentialGap/14));
    // 出场时间决定「兑现」：长期不踢球，训练效率打折
    const ss=p.seasonStats||{};
    const expectedMin=p.age<=20?900:p.age<=23?1800:p.age<=27?2400:2000;
    const exposure=clamp((Number(ss.minutes||0))/expectedMin,0.55,1.12);
    const base=(0.08+Math.random()*0.20)*response*(0.78+pro*0.22)*fatigueFactor*moraleFactor*ageFactor*potentialFactor*exposure;
    const cultureFactor=countryTrainingFactor(p,TRAIN_MAP[type]||[]);
    const adjustedBase=base*cultureFactor;
    const gains={};
    for(const k of TRAIN_MAP[type]||[]){const g=clamp(adjustedBase*(0.88+Math.random()*0.24),0.02,0.55);const before=p.stats[k]||0;const raw=(p.trainingProgress[k]||0)+g;const whole=Math.floor(raw);p.trainingProgress[k]=raw-whole;p.stats[k]=clamp(before+g,1,99);gains[k]=+(p.stats[k]-before).toFixed(2)}
    const fBefore=p.fatigue||0,fiBefore=p.fitness||0,mBefore=p.morale||0;
    p.fatigue=clamp(p.fatigue+7+(type==='身体'?3:0),0,100);p.fitness=clamp(p.fitness-4-(type==='身体'?2:0),0,100);p.development.lastTrainingDate=state.date;
    const oldCA=p.ca;
    let delta=recalcCA(p);
    if(p.id==='PUSER'){
      // 直接成长：年龄曲线 × 训练响应 × 职业度 × 比赛出勤 × 距离天花板的收敛
      const ceil=playerCeiling(p);
      const room=Math.max(0,ceil-p.ca);
      const ageCurve=p.age<=19?1.0:p.age<=22?0.85:p.age<=25?0.62:p.age<=28?0.38:p.age<=31?0.18:0.06;
      const perf=clamp(0.55+((p.seasonStats?.avgRating||6.4)-6.4)*0.35,0.3,1.3);
      const step=(0.035+0.075*response*(0.7+pro*0.3))*ageCurve*(0.75+0.5*fatigueFactor)*perf*(1-Math.exp(-room/10));
      if(step>0){p.ca=+clamp(p.ca+step,1,99).toFixed(3);delta=+(p.ca-oldCA).toFixed(3)}
    }
    updatePlayerMarketValue(p);
    p.growthHistory.push({date:state.date,type,caBefore:oldCA,caAfter:p.ca,gains});if(p.growthHistory.length>30)p.growthHistory.shift();
    return {ok:true,gains,caDelta:delta,type,status:{fatigue:Math.round(p.fatigue-fBefore),fitness:Math.round(p.fitness-fiBefore),morale:Math.round(p.morale-mBefore)}};
  }
  function lightweightNpcGrowth(targetDate){
    const monthKey=targetDate.slice(0,7);let changed=0;
    for(const p of Object.values(state.players)){
      if(p===state.player||p.id==='PUSER')continue;
      initDevelopment(p,hash(p.id));
      if(p.development.lastNpcGrowthMonth===monthKey)continue;
      if(p.age>34){p.development.lastNpcGrowthMonth=monthKey;continue;}
      // 月度只积累极小的属性微变化，不重算 CA；真人与 NPC 都拥有持续的职业成长，CA 在赛季末统一结算。
      const realFactor=p.isRealPlayer===true?0.72:1;
      const ageFactor=(p.age<=20?0.08:p.age<=23?0.06:p.age<=26?0.035:p.age<=29?0.012:0)*realFactor;
      const potential=Math.max(0,p.pa-p.ca);
      if(potential>0&&ageFactor>0){
        const g=Math.min(0.12,ageFactor*(0.7+p.development.professionalism*0.4)*(0.7+potential/100));
        const k=GROWTH_STATS[hash(p.id+monthKey)%GROWTH_STATS.length];
        p.stats[k]=clamp((p.stats[k]||0)+g,1,99);changed++;
      }
      if(p.age>=30){
        const k=GROWTH_STATS[hash(p.id+monthKey)%GROWTH_STATS.length];
        p.stats[k]=clamp((p.stats[k]||0)-0.006,1,99);
      }
      p.development.lastNpcGrowthMonth=monthKey;
    }
    return changed;
  }


