    const rawAge=Number(rp?.age); const metaAge=Number(meta?.age); const age=real?((Number.isFinite(rawAge)&&rawAge>=15)?rawAge:((Number.isFinite(metaAge)&&metaAge>=15)?metaAge:(Number(fallback.age)||24))):fallback.age;
