    for(let i=0;i<home;i++){const spGoal=r()<0.20;const sc=pickScorer('home',spGoal?'header':null);const as=pickScorer('home');const passBonus=(state.player&&state.player.clubId===f.homeClubId)?clamp(((Number(state.player.stats?.passing)||45)-50)/90,-0.25,0.35):0;
        const useAs=as&&sc&&as.id!==sc.id&&r()<clamp(0.68+passBonus*0.6,0.4,0.86)?as:null;events.push({minute:4+Math.floor(r()*87),type:'goal',team:'home',setPiece:spGoal?'header':null,scorerId:sc?sc.id:null,scorer:sc?sc.name:null,assistId:useAs?useAs.id:null,assist:useAs?useAs.name:null});}
    for(let i=0;i<away;i++){const spGoal=r()<0.20;const sc=pickScorer('away',spGoal?'header':null);const as=pickScorer('away');const useAs=as&&sc&&as.id!==sc.id&&r()<0.68?as:null;events.push({minute:4+Math.floor(r()*87),type:'goal',team:'away',setPiece:spGoal?'header':null,scorerId:sc?sc.id:null,scorer:sc?sc.name:null,assistId:useAs?useAs.id:null,assist:useAs?useAs.name:null});}
    for(let i=0;i<Math.min(3,Math.floor(r()*3));i++){events.push({minute:8+Math.floor(r()*82),type:'substitution',team:r()<0.5?'home':'away'});}
    // 牌面（2D）：先结算上一场停赛的服刑，再按犯规数掷黄/红（有具体球员），
