    return {score:{home,away},stats:{possession:{home:possession,away:100-possession},shots:{home:shotsH,away:shotsA},shotsOnTarget:{home:sotH,away:sotA},corners:{home:cornersH,away:cornersA},fouls:{home:foulsH,away:foulsA},xg:{home:xgH,away:xgA},setPieceGoals:{home:events.filter(e=>e.type==='goal'&&e.team==='home'&&e.setPiece).length,away:events.filter(e=>e.type==='goal'&&e.team==='away'&&e.setPiece).length},...(physNote?{physique:physNote}:{})},events,evaluation,formations:{home:ht.formation,away:at.formation},lineups:{home:lineupH,away:lineupA}};
